			{&g.layers[i].down, &g.layers[i].downFmt, "ffn_down_exps", w.Down.T},
			{&g.layers[i].shGate, &g.layers[i].shGateFmt, "ffn_gate_shexp", w.GateShexpT},
			{&g.layers[i].shUp, &g.layers[i].shUpFmt, "ffn_up_shexp", w.UpShexpT},
