		g.layers[i] = dnLayerWeights{
			qkv:    uint32(i * perBank),
			out:    uint32(i*perBank + g.qkvN()*c.NEmbd),
			conv:   base,
			gamma:  base + uint32(cw*c.Conv),
			a:      base + uint32(cw*c.Conv+c.HeadDim),
			dtBias: base + uint32(cw*c.Conv+c.HeadDim+c.NHeadV),

