		var moes []llm.MoEWeights
		for l := 0; l < c.NLayer; l++ {
			w, err := m.MoEWeights(l)
			if err != nil {
				return fmt.Errorf("moe layer %d: %w", l, err)
			}
			moes = append(moes, w)
		}
