	}
	// The real thing: layer 3 is bank 3.
	if err := g.Run(moeLayer); err != nil {
		t.Fatal(err)
	}
	got, err := compare(g.Out(), want.Vals[:len(g.Out())])
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("ffn_out-3 from bank %d: %v", moeLayer, got)
	if got.rms > 1e-2 {
